// Datacollecting v2.0: observational only; no actuator messages.
const now = Date.now(), INTERVAL = 300000, RETRY = 60000, TIMEOUT = 90000;
const out = Array(8).fill(null);
const keys = ['nappali','halo','gyerek','furdo','wc'];
const clone = x => JSON.parse(JSON.stringify(x));
const sqlTime = x => new Date(x).toISOString().slice(0,23).replace('T',' ');
const number = x => typeof x === 'number' && Number.isFinite(x) ? x : null;
const bool = x => typeof x === 'boolean' ? +x : null;
const fresh = (at, age) => typeof at === 'number' && at <= now+30000 && now-at<=age;
