 attempted:0,succeeded:0,failed:0,partial:0,unknown:0,sqlErrors:0,decisionErrors:0};
function diagnostic(code, details) {
 const d={at:new Date(now).toISOString(),code,...details};
 out[6]=out[6]?[].concat(out[6],{payload:d}):{payload:d};
 node.warn(JSON.stringify(d));
}
