 const details={tables:c.tables,source_received_at:c.sourceTimes,issues:c.issues,
  decision:c.decision,collector_version:2};
 const m={topic:`INSERT INTO snap_collection_cycles
 (cycle_id,sample_ts,attempted_at,completed_at,status,expected_tables,succeeded_tables,details_json)
 VALUES (?,?,?, ?,?,?,?,?) ON DUPLICATE KEY UPDATE `+
 (status==='pending'?'cycle_id=VALUES(cycle_id)':
 'completed_at=VALUES(completed_at),status=VALUES(status),succeeded_tables=VALUES(succeeded_tables),details_json=VALUES(details_json)'),
 payload:[c.id,sqlTime(Math.floor(c.at/1000)*1000),sqlTime(c.at),status==='pending'?null:sqlTime(now),status,
 Object.keys(c.tables).length,Object.values(c.tables).filter(t=>t.status==='success').length,JSON.stringify(details)],
 _dc:{kind:'audit',id:c.id}};
 out[5]=out[5]?[].concat(out[5],m):m;
}
function finish(timeout) {
 const c=st.cycle;
 const rows=Object.values(c.tables);
 if(timeout) for(const t of rows) if(t.status==='pending')t.status='unknown';
 const success=rows.filter(t=>t.status==='success').length;
 const status=rows.some(t=>t.status==='unknown')?'unknown':
  success===rows.length && !c.incomplete?'success':success?'partial':'failed';
 st[status==='success'?'succeeded':status]++;
 if(status==='success')st.lastSuccessAt=now;
 else diagnostic('collection_'+status,{cycle_id:c.id,tables:c.tables,issues:c.issues});
 st.nextSampleAt=status==='success' || (c.incomplete && rows.every(t=>t.status==='success'))?c.at+INTERVAL:now+RETRY;
 audit(c,status);st.cycle=null;
}
// Acknowledgements retain _dc through node-red-node-mysql; Catch retains it too.
if(msg._dc) {
 const a=msg._dc;
 if(a.kind==='audit') {
  if(msg.error){st.sqlErrors++;diagnostic('audit_sql_error',{cycle_id:a.id,code:String(msg.error.code||'SQL_ERROR')});}
 } else if(a.kind==='decision') {
  if(st.decisionPending?.id===a.id) {
   if(msg.error){st.decisionErrors++;st.decisionPending.retryAt=now+RETRY;
    diagnostic('decision_sql_error',{event_key:a.id,code:String(msg.error.code||'SQL_ERROR')});}
   else if(typeof msg.payload?.affectedRows==='number') {
    st.lastDecisionSig=st.decisionPending.sig;st.lastDecisionSuccessAt=now;
    st.lastDecisionEventKey=a.id;st.decisionPending=null;
   }
  }
 } else if(a.kind==='snapshot' && st.cycle?.id===a.id) {
  const t=st.cycle.tables[a.table];
  if(t?.status==='pending') {
   t.affected=number(msg.payload?.affectedRows);
   t.status=!msg.error && t.affected===t.expected?'success':'failed';
   if(t.status==='failed'){st.sqlErrors++;t.error=String(msg.error?.code||'ROW_COUNT_MISMATCH');}
   if(Object.values(st.cycle.tables).every(t=>t.status!=='pending'))finish(false);
  }
 }
} else if(msg.topic==='dc/v2/decision' && msg.payload?.plan?.zones) {
 st.decision=clone(msg.payload);st.decisionReceivedAt=now;
} else if(msg.payload && typeof msg.payload==='object' && !Array.isArray(msg.payload)
 && fresh(msg.payload._ts,600000) && msg.payload.sensors) {
 st.cache=clone(msg.payload);st.cacheReceivedAt=now;
}
if(st.cycle && now-st.cycle.at>TIMEOUT)finish(true);

// Decision key is reused after timeout; UNIQUE(event_key) makes retry idempotent.
if(st.decisionPending && now>=st.decisionPending.retryAt) {
 const d=st.decisionPending;
 out[7]=clone(d.message);d.retryAt=now+TIMEOUT;
} else if(!st.decisionPending && st.decision && fresh(st.decisionReceivedAt,600000)) {
 const d=st.decision,p=d.plan,s=p.strategy||{},plant=p.plant||{};
 const ov=Object.values(p.zones).map(z=>z.override);
 const known=ov.length===5 && ov.every(o=>o && ['manualTargetActive','manualForceOnActive','manualForceOffActive'].every(k=>typeof o[k]==='boolean'));
 const manual= d.floorMode==='manual' || ov.some(o=>o && (o.manualTargetActive===true||o.manualForceOnActive===true||o.manualForceOffActive===true));
 const manualFlag=manual?1:known?0:null;
 const enabled=bool(d.controlEnabled);
 const mode=enabled===0?'disabled':enabled===null?'unknown':manual?'manual':known?'auto':'unknown';
 const relevant={enabled,mode,floorMode:d.floorMode,strategy:s.mode,REPLACE_WITH_DEVICE_ID_01owed:s.floorHeatingAllowed,
  outdoor:s.outdoorTemp,forecast:s.forecastHigh,plant:clone({boiler:plant.boiler||null,pump:plant.pump||null}),
  zones:Object.fromEntries(Object.entries(p.zones).map(([k,z])=>[k,{relay:z.relay,override:z.override,
   control:z.control,plan:{want:z.plan?.want,reasons:z.plan?.reasons}}]))};
 // Archive each real planner evaluation once. A cached plan is never a new decision.
 for(const a of Object.values(relevant.plant))if(a?.antiShortCycle) a.antiShortCycle={hold:a.antiShortCycle.hold};
 const sig=JSON.stringify({plannedAt:p.meta?.plannedAt,...relevant});
 st.currentDecisionSummary={mode,manualFlag,sig};
 if(sig!==st.lastDecisionSig) {
  const at=Date.parse(p.meta?.plannedAt);
  if(Number.isFinite(at) && Math.abs(now-at)<=600000) {
   const id='decision-'+node.id+'-'+now+'-'+(++st.seq);
   const details={...d,quality:{forecastHighMayBeOutdoorFREPLACE_WITH_DEVICE_ID_01back:true,
    manualOrigin:'timed_UI_or_floor_mode_only',collectorReceivedAt:new Date(st.decisionReceivedAt).toISOString()}};
   const message={topic:`INSERT INTO snap_heating_decisions
    (event_key,ts,recorded_at,season_key,building_state,control_mode,control_enabled,floor_mode,
     strategy_mode,floor_REPLACE_WITH_DEVICE_ID_01owed,outdoor_temp,forecast_high,boiler_want,boiler_on,pump_want,pump_on,manual_override,decision_json)
    VALUES (?,?,UTC_TIMESTAMP(3),?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE event_key=VALUES(event_key)`,
    payload:[id,sqlTime(at),'2026-2027','post_insulation_2026',mode,enabled,d.floorMode||null,s.mode||null,
     bool(s.floorHeatingAllowed),number(s.outdoorTemp),number(s.forecastHigh),bool(plant.boiler?.want),
     plant.boiler?.found===true?bool(plant.boiler.currentOn):null,bool(plant.pump?.want),
     plant.pump?.found===true?bool(plant.pump.currentOn):null,manualFlag,JSON.stringify(details)],
    _dc:{kind:'decision',id}};
   st.decisionPending={id,sig,message:clone(message),retryAt:now+TIMEOUT};out[7]=message;
  }
 }
}

// Sample the latest cache, not a fictitious new sensor measurement.
if(!msg._dc && !st.cycle && st.cache && fresh(st.cache._ts,600000)
 && now-st.lastAttemptAt>=RETRY && now-st.lastSuccessAt>=INTERVAL && now>=(st.nextSampleAt||0)) {
 const p=st.cache,ts=sqlTime(now),id='cycle-'+node.id+'-'+now+'-'+(++st.seq);
 const issues=[],tables={},tasks=Array(5).fill(null);
 function task(index,table,columns,rows) {
  if(!rows.length)return;
  const params=rows.flat();
  const placeholders=rows.map(r=>'('+r.map(()=>'?').join(',')+')').join(',');
  tasks[index]={topic:`INSERT INTO ${table} (${columns}) VALUES ${placeholders}`,payload:params,
   _dc:{kind:'snapshot',id,table}};
  tables[table]={expected:rows.length,status:'pending'};
 }
 const w=p.weather;
 if(w && fresh(p._updated?.weather,3600000)) {
  const time=x=>typeof x==='string' && /^\d{2}:\d{2}/.test(x)?x.slice(0,5):null;
  task(0,'snap_weather','ts,temp,humidity,wind,gust,wx_code,temp_min,temp_max,sunrise,sunset',
   [[ts,number(w.temp),number(w.humidity),number(w.wind),number(w.gust),number(w.code),number(w.tempMin),number(w.tempMax),time(w.sunrise),time(w.sunset)]]);
 }else issues.push('weather_missing_or_stale');
 const sensors=[];
 for(const room of keys) {
  const s=p.sensors?.th?.[room];if(!s){issues.push('sensor_missing:'+room);continue;}
  const online=s.online===true && fresh(p._updated?.th?.[room],900000);
  if(!online)issues.push('sensor_offline_or_stale:'+room);
  sensors.push([ts,room,online?number(s.temp):null,online?number(s.hum):null,number(s.battery),+online]);
 }
 task(1,'snap_sensors_th','ts,room,temp,humidity,battery,online',sensors);
 const ac=p.ac;
 if(ac && fresh(p._updated?.ac,1800000) && bool(ac.power)!==null && bool(ac.offline)!==null)
  task(2,'snap_ac','ts,power,room_temp,set_temp,mode_code,offline',[[ts,+ac.power,number(ac.roomTemp),number(ac.setTemp),number(ac.modeCode??ac.mode),+ac.offline]]);
 else issues.push('ac_missing_or_stale');
 const aliases={'Nappali fűtéskör':'nappali','Hálószoba fűtéskör':'halo','Gyerekszoba fűtéskör':'gyerek',
  'Gyerekszoba fűtéskör':'gyerek','Fürdőszoba fűtéskör':'furdo','WC fűtéskör':'wc','Kazán':'kazan',
  'Kazán On/Off':'kazan','Szivattyú':'szivattyu','Szivattyú On/Off':'szivattyu'};
 const relays=[],seen=new Set();
 for(const [name,value] of Object.entries(p.sensors?.switches?.futes||{})) {
  const key=aliases[name];
  if(!key){issues.push('unmapped_relay:'+name);continue;}
  if(seen.has(key)){issues.push('duplicate_relay_alias:'+key);continue;}
  if(bool(value)===null||!fresh(p._updated?.switches?.futes?.[name],600000)){issues.push('relay_unknown_or_stale:'+key);continue;}
  seen.add(key);relays.push([ts,name,+value]);
 }
 task(3,'snap_heating','ts,relay_name,state',relays);
 const shutters=[];
 for(const [room,labels] of Object.entries(p.sensors?.shutters||{}))
  for(const [label,s] of Object.entries(labels||{}))if(s && typeof s==='object')
   shutters.push([ts,room,label,number(s.pct),typeof s.motor==='string'?s.motor:null]);
 task(4,'snap_shutters','ts,room,label,position_pct,motor',shutters);
 if(Object.keys(tables).length) {
  const d=st.decision,decisionFresh=d && fresh(st.decisionReceivedAt,600000);
  const c={id,at:now,tables,issues,sourceTimes:p._updated||{},
   incomplete:Object.keys(tables).length!==5 || sensors.length!==5 || relays.length!==7,
   decision:{event_key:decisionFresh && st.currentDecisionSummary?.sig===st.lastDecisionSig?st.lastDecisionEventKey||null:null,
    received_at:decisionFresh?st.decisionReceivedAt:null,planned_at:decisionFresh?d.plan?.meta?.plannedAt:null,
    control_mode:decisionFresh?st.currentDecisionSummary?.mode||'unknown':'unknown',
    manual_override:decisionFresh?st.currentDecisionSummary?.manualFlag??null:null,
    control_enabled:decisionFresh?d.controlEnabled:null,floor_mode:decisionFresh?d.floorMode:null,
    stale:!decisionFresh}};
  st.cycle=c;st.lastAttemptAt=now;st.attempted++;audit(c,'pending');
  for(let i=0;i<5;i++)out[i]=tasks[i];
 }
}
const age=now-(st.lastSuccessAt||st.startedAt);
if(now-(st.decisionReceivedAt||st.startedAt)>600000 && now-(st.lastDecisionGapWarningAt||0)>600000) {
 diagnostic('decision_source_gap',{last_received_at:st.decisionReceivedAt||null});st.lastDecisionGapWarningAt=now;
}
if(age>600000 && now-(st.lastGapWarningAt||0)>600000) {
 diagnostic('collection_gap',{seconds:Math.round(age/1000),last_success_at:st.lastSuccessAt||null});st.lastGapWarningAt=now;
}
const health={version:2,attempted:st.attempted,succeeded:st.succeeded,partial:st.partial,failed:st.failed,
 unknown:st.unknown,sqlErrors:st.sqlErrors,decisionErrors:st.decisionErrors,lastAttemptAt:st.lastAttemptAt,
 lastSuccessAt:st.lastSuccessAt,lastDecisionSuccessAt:st.lastDecisionSuccessAt||null,
 inFlight:st.cycle?.id||null,cacheReceivedAt:st.cacheReceivedAt||null};
flow.set('dc_v2_health',health);context.set('dcV2',st);
node.status({fill:age>600000?'red':st.cycle?'blue':st.lastSuccessAt?'green':'yellow',shape:st.cycle?'ring':'dot',
 text:`v2 OK:${st.succeeded} partial:${st.partial} fail:${st.failed+st.unknown} SQL:${st.sqlErrors} | ${st.lastSuccessAt?new Date(st.lastSuccessAt).toISOString().slice(11,19)+' UTC':'waiting'}`});
return out;

let d = msg.payload || {};
let daily = d.daily || {};
let hourly = d.hourly || {};

let minT = daily.temperature_2m_min ? daily.temperature_2m_min[0] : null;
let maxT = daily.temperature_2m_max ? daily.temperature_2m_max[0] : null;

if (minT == null && hourly.temperature_2m) {
