const TZ = 'Europe/Budapest';

// ---- Beállítások ----
const SAMPLE_MIN = 5;                         // nálad 5 perc a mintavételezés
const SAMPLE_MS  = SAMPLE_MIN * 60 * 1000;
const MAX_GAP_MS = 2 * SAMPLE_MS;             // ha ennél nagyobb a rés, akkor ne számoljuk bele teljesen

const RELAY_ON_VALUE  = 1;                    // relay_state: 1 = ON
const BOILER_ON_VALUE = 1;                    // boiler_state: 1 = ON

const now = new Date();
const isoDate = new Intl.DateTimeFormat('en-CA', { timeZone: TZ }).format(now); // YYYY-MM-DD
const huDateLong = new Intl.DateTimeFormat('hu-HU', {
  timeZone: TZ, weekday: 'long', year: 'numeric', month: 'long', day: '2-digit'
}).format(now);

// ---- Inputok ----
const sql     = msg.payload.sql || [];
const f       = msg.payload.forecast || {};
const fx      = msg.payload.fx || {};
const lunch   = msg.payload.lunch || {};
const nameday = msg.payload.nameday || {};
const kuka = msg.payload.kuka || msg.payload.kukaReminder || '';


// ---- Helpers ----
const toMs = (ts) => {
  if (ts == null) return null;

  // number: epoch sec vagy ms
  if (typeof ts === 'number' && Number.isFinite(ts)) {
    return ts < 1e12 ? ts * 1000 : ts;
  }

  const s = String(ts).trim();

  // numeric string: epoch sec vagy ms
  if (/^\d+$/.test(s)) {
    const n = Number(s);
    if (!Number.isFinite(n)) return null;
    return n < 1e12 ? n * 1000 : n;
  }

  const t = Date.parse(s);
  return Number.isFinite(t) ? t : null;
};

const ICON = {
  sun: '☀️',
  weather: '🌦',
  rain: '☔',
  wind: '🌬️',     // 💨 helyett ez “szelesebb”
  sunrise: '🌅',
  sunset: '🌇',
  lunch: '🍽️',
  eur: '💶',
  tip: '💡'
};

const fnum = (n, d = 1) =>
  (n == null || Number.isNaN(Number(n))) ? '-' : Number(n).toFixed(d);

const avg = (a) => a.length ? (a.reduce((x, y) => x + y, 0) / a.length) : null;
const min = (a) => a.length ? Math.min(...a) : null;
const max = (a) => a.length ? Math.max(...a) : null;

const fmtHHMM = (ms) => {
  if (ms == null) return 'n/a';
 if (ms <= 0) return '00:00';
  const totalMin = Math.floor(ms / 60000);
  const hh = String(Math.floor(totalMin / 60)).padStart(2, '0');
  const mm = String(totalMin % 60).padStart(2, '0');
  return `${hh}:${mm}`;
};

const timeHHMM = (s) => {
  if (!s) return '-';
  // open-meteo: "YYYY-MM-DDTHH:MM"
  const m = String(s).match(/T(\d{2}:\d{2})/);
  if (m) return m[1];
  try {
    return new Date(s).toLocaleTimeString('hu-HU', {
      timeZone: TZ, hour: '2-digit', minute: '2-digit'
    });
  } catch {
    return '-';
  }
};

// ---- ON-idő számolás (rés-kezeléssel) ----
function calcOnMsClamped(points,key,onValue) {
 const m=new Map();
 for(const p of points||[]) {
  const ms=toMs(p.timestamp);if(ms===null)continue;
  const state=p[key]===0||p[key]===1?p[key]:null;
  m.set(ms,state);
 }
 const arr=Array.from(m.entries()).sort((a,b)=>a[0]-b[0]);
 let onMs=0,knownMs=0;
 for(let i=0;i<arr.length-1;i++) {
  const dt=arr[i+1][0]-arr[i][0];
  if(arr[i][1]===null||dt<=0||dt>MAX_GAP_MS)continue;
  knownMs+=dt;if(arr[i][1]===onValue)onMs+=dt;
 }
 return knownMs?onMs:null;
}
const qualityRooms=Object.entries(sql.reduce((a,r)=>{
 const k=r.zone_key||r.room_name||'unknown';
 const v=a[k]||(a[k]={total:0,known:0,offline:0});
 v.total++;if(r.relay_state===0||r.relay_state===1)v.known++;
 if(r.sensor_online===0)v.offline++;return a;
},{})).map(([k,v])=>k+': reléadat '+v.known+'/'+v.total+', offline szenzorminta '+v.offline).join(' · ');
// ---- Kültéri / kazán sorozat dedup timestamp szerint ----
// Mivel minden szobához van rekord ugyanazzal a timestamp-pel, itt timestamp alapján dedupolunk.
const byTs = new Map(); // ms -> { outdoor_temp, outdoor_hum, boiler_state }
for (const r of sql) {
  const ms = toMs(r.timestamp);
  if (ms == null) continue;
  if (!byTs.has(ms)) {
    byTs.set(ms, {
      timestamp: r.timestamp,
      outdoor_temp: r.outdoor_temp,
      outdoor_hum: r.outdoor_hum,
      boiler_state: r.boiler_state
    });
  }
}
const uniqTs = Array.from(byTs.values());

const outTemps = uniqTs.filter(x => x.outdoor_temp != null).map(x => Number(x.outdoor_temp));
const outHums  = uniqTs.filter(x => x.outdoor_hum  != null).map(x => Number(x.outdoor_hum));

const outAvgT = fnum(avg(outTemps), 1);
const outAvgH = fnum(avg(outHums), 0);

const boilerOnMs   = calcOnMsClamped(uniqTs, 'boiler_state', BOILER_ON_VALUE);
const boilerOnHHMM = fmtHHMM(boilerOnMs);

// ---- Szobánként aggregálás + ON idő ----
const rooms = {}; // room -> { t:[], h:[], series:[{timestamp, relay_state}] }

for (const r of sql) {
  const room = (r.room_name || r.relay_name || 'Ismeretlen').toString();
  if (!rooms[room]) rooms[room] = { t: [], h: [], series: [] };

  if (r.indoor_temp != null) rooms[room].t.push(Number(r.indoor_temp));
  if (r.indoor_hum  != null) rooms[room].h.push(Number(r.indoor_hum));

  rooms[room].series.push({ timestamp: r.timestamp, relay_state: r.relay_state });
}

let rows = '';
const roomNames = Object.keys(rooms).sort((a, b) => a.localeCompare(b, 'hu'));
for (const room of roomNames) {
  const s = rooms[room];
  const onMs = calcOnMsClamped(s.series, 'relay_state', RELAY_ON_VALUE);

  rows += `<tr>
  <td style="text-align:left;padding:8px 10px;border:1px solid #e5e7eb;font-size:13px;font-weight:600;white-space:nowrap;">${room}</td>
  <td style="text-align:right;padding:8px 10px;border:1px solid #e5e7eb;font-size:13px;font-variant-numeric:tabular-nums;">${fnum(avg(s.t), 1)} °C</td>
  <td style="text-align:right;padding:8px 10px;border:1px solid #e5e7eb;font-size:13px;font-variant-numeric:tabular-nums;">${fnum(min(s.t), 1)} °C</td>
  <td style="text-align:right;padding:8px 10px;border:1px solid #e5e7eb;font-size:13px;font-variant-numeric:tabular-nums;">${fnum(max(s.t), 1)} °C</td>
  <td style="text-align:right;padding:8px 10px;border:1px solid #e5e7eb;font-size:13px;font-variant-numeric:tabular-nums;">${fnum(avg(s.h), 0)} %</td>
  <td style="text-align:right;padding:8px 10px;border:1px solid #e5e7eb;font-size:13px;font-variant-numeric:tabular-nums;color:#0f766e;"><b>${fmtHHMM(onMs)}</b></td>
