/**
 * Outdoor Temp (Open-Meteo) normalize v4
 * Node-RED Function node
 *
 * Input: Open-Meteo API response
 * Output topic: "weather"
 *
 * Output payload:
 * {
 *   ts,
 *   outdoor,
 *   forecastTemp,
 *   humidity,
 *   wx,
 *   wind,
 *   gust,
 *   forecast: {
 *     horizonHours,
 *     nextHourTemp,
 *     nextHourTs,
 *     minNextHours,
 *     maxNextHours
 *   },
 *   forecastHours: [
 *     { ts, tempC, wx, windKph, pop }
 *   ],
 *   source: {
 *     utc_offset_seconds,
 *     timezone
 *   }
 * }
 */

const HORIZON_HOURS = 6;

// ------------------------------
// Segédfüggvények
// ------------------------------

function num(value) {
  if (value === null ||
    value === undefined ||
    value === "" ||
    typeof value === "boolean") {
    return null;
  }

  const n = Number(
    typeof value === "string"
      ? value.trim().replace(",", ".")
      : value
  );

  return Number.isFinite(n) ? n : null;
}

function okTemp(value) {
  return (
    typeof value === "number" &&
    Number.isFinite(value) &&
    value > -50 &&
    value < 60
  );
}

function parseTimeWithOffset(value, offsetSeconds) {
  if (typeof value !== "string") return NaN;

  const hasZone =
    /Z$/i.test(value) ||
    /[+-]\d{2}:\d{2}$/.test(value) ||
    /[+-]\d{4}$/.test(value);

  if (hasZone) {
    return Date.parse(value);
  }

  // Az Open-Meteo helyi időt küld timezone=auto esetén.
  // A választott UTC offset alapján UTC-re alakítjuk.
  const base = Date.parse(value + "Z");

  if (!Number.isFinite(base)) return NaN;

  const offset = num(offsetSeconds);

  return base - (offset ?? 0) * 1000;
}

function isoTime(timestamp) {
  return Number.isFinite(timestamp)
    ? new Date(timestamp).toISOString()
    : null;
}

function fail(message) {
  node.status({
    fill: "red",
    shape: "ring",
    text: "weather: ERROR"
  });

  node.error("Open-Meteo: " + message, msg);
  return null;
}

// ------------------------------
// 1. API válasz feldolgozása
// ------------------------------

let p = msg.payload;

try {
  // Buffer támogatás
  if (typeof Buffer !== "undefined" &&
    Buffer.isBuffer(p)) {
    p = p.toString("utf8");
  }

  // JSON szöveg támogatás
  if (typeof p === "string") {
    p = JSON.parse(p);
  }

} catch (error) {
  return fail(
    "JSON feldolgozási hiba: " + error.message
  );
}

// Egyes integrációk a body mezőbe teszik a választ.
if (p &&
  typeof p === "object" &&
  !Array.isArray(p) &&
  p.body !== undefined &&
  !p.current &&
  !p.hourly) {

  let body = p.body;

  try {
    if (typeof body === "string") {
      body = JSON.parse(body);
    }

    if (body && typeof body === "object") {
      p = body;
    }
  } catch (error) {
    return fail(
      "Body JSON feldolgozási hiba: " +
      error.message
    );
  }
}

if (!p || typeof p !== "object" || Array.isArray(p)) {
  return fail("Üres vagy érvénytelen API válasz.");
}

// HTTP ellenőrzés
const httpStatus = num(msg.statusCode);

if (httpStatus !== null && httpStatus !== 200) {
  const reason =
    p.reason ||
    p.message ||
    JSON.stringify(p).slice(0, 300);

  return fail(
    "HTTP " + httpStatus + " - " + reason
  );
}

// Open-Meteo API hiba
if (p.error === true) {
  return fail(
    "API hiba: " + (p.reason || "Ismeretlen hiba")
  );
}

// ------------------------------
// 2. Aktuális időjárás
// ------------------------------

const offsetSec = num(p.utc_offset_seconds);

let outdoor = num(
  p.current?.temperature_2m ??
  p.current_weather?.temperature
);

const humidity = num(
  p.current?.relative_humidity_2m ??
  p.current?.relativehumidity_2m
);

const wx = num(
  p.current?.weather_code ??
  p.current_weather?.weathercode
);

const wind = num(
  p.current?.wind_speed_10m ??
  p.current_weather?.windspeed
);

const gust = num(
  p.current?.wind_gusts_10m
);

// ------------------------------
// 3. Óránkénti előrejelzés
// ------------------------------

const hourly = p.hourly || {};

const times = Array.isArray(hourly.time)
  ? hourly.time
  : [];

const temps = Array.isArray(hourly.temperature_2m)
  ? hourly.temperature_2m
  : [];

const weatherCodes = Array.isArray(hourly.weather_code)
  ? hourly.weather_code
  : [];

const winds = Array.isArray(hourly.wind_speed_10m)
  ? hourly.wind_speed_10m
  : [];

const precipitation = Array.isArray(
  hourly.precipitation_probability
)
  ? hourly.precipitation_probability
  : [];

const now = Date.now();
const end = now + HORIZON_HOURS * 3600000;

const REPLACE_WITH_DEVICE_ID_01Hours = [];

for (let i = 0; i < Math.min(times.length, temps.length); i++) {

  const ts = parseTimeWithOffset(
    times[i],
    offsetSec
  );

  const temp = num(temps[i]);

  if (!Number.isFinite(ts) || !okTemp(temp)) {
    continue;
  }

  REPLACE_WITH_DEVICE_ID_01Hours.push({
    timestamp: ts,
    ts: isoTime(ts),
    tempC: temp,
    wx: num(weatherCodes[i]),
    windKph: num(winds[i]),
    pop: num(precipitation[i])
  });
}

REPLACE_WITH_DEVICE_ID_01Hours.sort(
  (a, b) => a.timestamp - b.timestamp
);

// ------------------------------
// 4. FREPLACE_WITH_DEVICE_ID_01back kültéri hőmérséklet
// ------------------------------

// Ha nincs current adat, a legközelebbi
// órás mérési/előrejelzési értéket használjuk.

let outdoorFREPLACE_WITH_DEVICE_ID_01back = false;

if (!okTemp(outdoor)) {

  let nearest = null;
  let nearestDiff = Infinity;

  for (const hour of REPLACE_WITH_DEVICE_ID_01Hours) {

    const diff = Math.abs(
      hour.timestamp - now
    );

    if (diff < nearestDiff) {
      nearestDiff = diff;
      nearest = hour;
    }
  }

  // Legfeljebb 90 perces eltérést fogadunk el.
  if (nearest && nearestDiff <= 90 * 60000) {
    outdoor = nearest.tempC;
    outdoorFREPLACE_WITH_DEVICE_ID_01back = true;
  }
}

// ------------------------------
// 5. Következő 6 óra
// ------------------------------

const futureHours = REPLACE_WITH_DEVICE_ID_01Hours.filter(
  h => h.timestamp >= now &&
    h.timestamp <= end
);

const nextHour = futureHours.length > 0
  ? futureHours[0]
  : null;

let minNextHours = null;
let maxNextHours = null;

if (futureHours.length > 0) {

  const values = futureHours.map(
    h => h.tempC
  );

  minNextHours = Math.min(...values);
  maxNextHours = Math.max(...values);
}

// Ha nincs jövőbeli adat, ne használjunk
// korlátlanul régi előrejelzést.
let forecastTemp = minNextHours;

if (!okTemp(forecastTemp) && okTemp(outdoor)) {
  forecastTemp = outdoor;
}

const forecast = {
  horizonHours: HORIZON_HOURS,
  nextHourTemp: nextHour
    ? nextHour.tempC
    : null,
  nextHourTs: nextHour
    ? nextHour.ts
    : null,
  minNextHours,
  maxNextHours
};

const forecastHours = futureHours.map(h => ({
  ts: h.ts,
  tempC: h.tempC,
  wx: h.wx,
  windKph: h.windKph,
  pop: h.pop
}));

// ------------------------------
// 6. Végső validáció
// ------------------------------

if (!okTemp(outdoor)) {

  node.warn({
    problem: "Nincs használható kültéri hőmérséklet",
    httpStatus,
    payloadType: typeof p,
    payloadKeys: Object.keys(p),
    current: p.current || null,
    current_weather: p.current_weather || null,
    hourlyCount: temps.length,
    hourlyTimeCount: times.length,
    apiReason: p.reason || null
  });

  return fail(
    "Nem található érvényes kültéri hőmérséklet. " +
    "Ellenőrizd az API választ a Debug panelen."
  );
}

// ------------------------------
// 7. Kimeneti üzenet
// ------------------------------

msg.topic = "weather";

msg.payload = {
  ts: new Date(now).toISOString(),

  outdoor,
  forecastTemp,

  humidity,
  wx,
  wind,
  gust,

  forecast,
  forecastHours,

  source: {
    utc_offset_seconds: offsetSec,
    timezone: p.timezone ?? null
  }
};

// ------------------------------
// 8. Node státusz
// ------------------------------

const outdoorText = outdoor.toFixed(1);
const forecastText = okTemp(forecastTemp)
  ? forecastTemp.toFixed(1)
  : "?";

node.status({
  fill: outdoorFREPLACE_WITH_DEVICE_ID_01back ? "yellow" : "green",
  shape: "dot",
  text:
    `out:${outdoorText}°C | ` +
    `fc(min6h):${forecastText}°C` +
    (outdoorFREPLACE_WITH_DEVICE_ID_01back ? " | fREPLACE_WITH_DEVICE_ID_01back" : "")
});

if (outdoorFREPLACE_WITH_DEVICE_ID_01back) {
  node.warn(
    "Open-Meteo: current hőmérséklet hiányzik, " +
    "órás adatból helyettesítve: " +
    outdoorText + "°C"
  );
}

return msg;

// Normalize snapshot v2.1 (HVAC core state)
// Input: join snapshot { sensors, relayF, relayL, ac, weather, time }
// Output topic: hvac/state

const p = msg.payload || {};
const cachedAc = p.ac || flow.get("hvac_ac_telemetry") || null;
const cacheAt = Number(cachedAc?.receivedAt) || 0;
const acState = cachedAc ? { ...cachedAc, offline:cachedAc.offline===true || Date.now()-cacheAt>15*60000 } :
  {power:null,roomTemp:null,setTemp:null,modeCode:null,pending:false,offline:true,receivedAt:null};

// AC polls are independent; only the five core sources belong in the Join.
const nowMs=Date.now();
const criticalKeys=["sensors","relayF","relayL","time"];
const missingCritical=criticalKeys.filter(k=>p[k]===undefined || p[k]===null);
if(missingCritical.length){
  node.status({fill:"yellow",shape:"ring",text:"Hiányos core snapshot · döntés kihagyva"});
  node.warn("Normalize snapshot: döntés kihagyva, hiányzó core forrás: "+missingCritical.join(", "));
  return null;
}
if(p.weather && typeof p.weather==="object")
  context.set("lastWeather",{value:p.weather,at:nowMs});
const lastWeather=context.get("lastWeather");
const weatherCached=!p.weather && lastWeather && nowMs-lastWeather.at<=30*60000;
if(weatherCached)p.weather=lastWeather.value;
const quality={weatherCached:!!weatherCached,weatherMissing:!p.weather,acCached:!p.ac,
 acUnknown:!cachedAc,acAgeMs:cacheAt?nowMs-cacheAt:null};
node.status({fill:quality.weatherMissing || quality.acUnknown?"yellow":"green",shape:"dot",
 text:quality.weatherMissing?"Core teljes · időjárás nincs":"Core 5/5 · klíma külön cache"});

const num = v => {
  if (v === null || v === undefined || v === "") return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

function strip(s) {
  return String(s || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();
}

function roomKey(name) {
  const n = strip(name);
  if (n.includes("nappali")) return "nappali";
  if (n.includes("haloszoba") || n.includes("halo")) return "halo";
  if (n.includes("gyerek") || n.includes("Gyerekszoba")) return "gyerek";
  if (n.includes("furdo")) return "furdo";
  if (n === "wc" || n.includes(" wc")) return "wc";
  return n || "unknown";
}

function normalizeSensors(list) {
  const arr = Array.isArray(list) ? list : [];
  return arr
    .map(s => {
      if ("temperature" in (s || {}) || "humidity" in (s || {})) {
        return { key: roomKey(s.name), name: s.name || null, online: s.online,
          temp: s.online === false ? null : num(s.temperature), rh: s.online === false ? null : num(s.humidity), measuredAt: s.measuredAt ?? null };
      }
      if (s && s.display_category === "temperatureAndHumiditySensor") {
        return {
          key: roomKey(s.name),
          name: s.name || null,
          online: s.online,
          measuredAt: s.state?.temperature?.updated_at ?? null,
          temp: s.online === false ? null : num(s.state?.temperature?.temperature),
          rh: s.online === false ? null : num(s.state?.humidity?.humidity),
        };
      }
      return null;
    })
    .filter(Boolean)
    .filter(s => s.online === false || s.temp !== null || s.rh !== null);
}

function normalizeRelays(list) {
  const arr = Array.isArray(list) ? list : (list && typeof list === "object" ? [list] : []);
  const out = [];

  for (const dev of arr) {
    if (dev && ("channel" in dev || "device" in dev) && ("state" in dev)) {
      const st = String(dev.state || "unknown").toLowerCase();
      out.push({
        device: dev.device || null,
        channel: dev.channel || null,
        name: dev.name || null,
        state: st,
        on: ["on","true","1","bekapcsolva","active","closed"].includes(st)
      });
      continue;
    }

    const toggle = dev?.state?.toggle;
    const labelMap = dev?.tags?.toggle || {};
    const devName = dev?.name || "Device";

    if (toggle && typeof toggle === "object") {
      for (const [ch, obj] of Object.entries(toggle)) {
        const st = String(obj?.toggleState || "unknown").toLowerCase();
        out.push({
          device: devName,
          channel: ch,
          name: labelMap?.[ch] || `${devName} #${ch}`,
          state: st,
          on: ["on","true","1","bekapcsolva","active","closed"].includes(st)
        });
      }
      continue;
    }
  }
  return out;
}

const rooms = normalizeSensors(p.sensors);
const floorRelays = normalizeRelays(p.relayF);
const lineRelays = normalizeRelays(p.relayL);

const roomTemps = rooms.map(r => r.temp).filter(v => v !== null);
const roomHums = rooms.map(r => r.rh).filter(v => v !== null);

const avgTemp = roomTemps.length ? Math.round((roomTemps.reduce((a,b)=>a+b,0)/roomTemps.length)*10)/10 : null;
const avgRh   = roomHums.length ? Math.round((roomHums.reduce((a,b)=>a+b,0)/roomHums.length)*10)/10 : null;

msg.topic = "hvac/state";
msg.payload = {
  meta: { version: 24, updatedAt: new Date().toISOString(), sourceQuality:quality },

  time: p.time || null,

  indoor: { rooms, avgTemp, avgRh },

  outdoor: {
    temp: num(p.weather?.outdoor),
    forecastTemp: num(p.weather?.forecastTemp),
    humidity: num(p.weather?.humidity),
    wx: (p.weather?.wx ?? null),
    wind: num(p.weather?.wind),
    gust: num(p.weather?.gust),
    forecast: p.weather?.forecast ?? null,
    source: p.weather?.source ?? null
  },

  relays: { floor: floorRelays, line: lineRelays },

  ac: acState
};

return msg;

// Zone Context Builder v3.2 — fresh sensor cache + true hysteresis
// Input: msg.payload = hvac/state

const state = msg.payload || {};
const now = new Date();
const nowMs = now.getTime();

function num(v) {
  if (v === null || v === undefined || v === "") return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}
function norm(s) {
  return String(s || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();
}
function okTemp(v) {
  return Number.isFinite(v) && v > -50 && v < 60;
}
function isActiveUntil(iso) {
  if (!iso) return false;
  const ts = Date.parse(iso);
  return Number.isFinite(ts) && ts > nowMs;
}
function isBetweenHour(hour, s, e) {
  if (hour === null) return false;
  return s < e ? (hour >= s && hour < e) : (hour >= s || hour < e);
}

// --- Heating rules konstansok (v0.4.1)
// orig -> const BASE_SETPOINTS = { nappali: 25, halo: 25, gyerek: 25, furdo: 25, wc: 25 };
const BASE_SETPOINTS = { nappali: 24.2, halo: 23.0, gyerek: 23.5, furdo: 23.5, wc: 22.5 };

const HYST = 1.0;
const NIGHT_DELTA = 1.5;
const SENSOR_CACHE_MAX_AGE_MS = 15 * 60 * 1000;
const SCHEDULE = {
  reggeli_melegites: { start: 5, end: 8 },
  nappali: { start: 8, end: 22 },
  ejszaka: { start: 20, end: 5 },
  furdo_kivetel: { start: 17, end: 19 }
};

// --- WEATHER COMP görbe
function weatherOffset(tOut) {
  if (!okTemp(tOut)) return 0;
  let off;
  if (tOut <= -10) off = 0.8;
  else if (tOut <= 0)   off = 0.8 - (0.8 - 0.4) * ((tOut - (-10)) / 10);
  else if (tOut <= 10)  off = 0.4 - (0.4 - 0.1) * (tOut / 10);
  else if (tOut <= 15)  off = 0.1 - (0.1 - 0.0) * ((tOut - 10) / 5);
  else if (tOut <= 20)  off = 0.0 - (0.0 - (-0.3)) * ((tOut - 15) / 5);
  else off = -0.3;
  return Math.max(-0.8, Math.min(0.8, off));
}

// overrides (UI később)
const zoneOverrides = flow.get("hvac_zone_overrides") || {};

// idő / mód
const t = state.time || {};
// Shared policy embedded in Zone Context; Budapest calendar, demand-driven only.
const localParts=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{
 timeZone:'Europe/Budapest',hour:'2-digit',month:'2-digit',hourCycle:'h23'
}).formatToParts(now).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));
const localHour=Number(localParts.hour), localMonth=Number(localParts.month);
const heatingSeason=localMonth>=10 || localMonth<=4;
const morning=localHour>=5 && localHour<8;
const sleep=localHour>=20 || localHour<5;
const hybrid={version:1,timezone:'Europe/Budapest',hour:localHour,month:localMonth,
 heatingSeason,morning,sleep,
 source:heatingSeason&&morning?'floor':'ac',
 floorAllowed:heatingSeason&&morning,
 acHeatAllowed:!(heatingSeason&&morning),
 heatOn:sleep?21.5:24,heatOff:sleep?22:25,
 bedroomTarget:sleep?22:null,
 morningWindow:'05:00–08:00',sleepWindow:'20:00–05:00',seasonWindow:'október–április'};

const hour = hybrid.hour;
flow.set("hvac_hybrid_policy", hybrid);

let mode = "nappali";
if (isBetweenHour(hour, SCHEDULE.reggeli_melegites.start, SCHEDULE.reggeli_melegites.end)) mode = "reggel";
else if (isBetweenHour(hour, SCHEDULE.ejszaka.start, SCHEDULE.ejszaka.end)) mode = "ejszaka";

// outdoor: forecastTemp prefer
const tOutNow = num(state.outdoor?.temp);
const tOutForecast = num(state.outdoor?.forecastTemp);
const tOutUsed = okTemp(tOutForecast) ? tOutForecast : (okTemp(tOutNow) ? tOutNow : null);
const tOutSource = okTemp(tOutForecast) ? "forecastTemp" : (okTemp(tOutNow) ? "current" : "none");
const wOff = weatherOffset(tOutUsed);

// inputs
const rooms = Array.isArray(state.indoor?.rooms) ? state.indoor.rooms : [];
const floorRelays = Array.isArray(state.relays?.floor) ? state.relays.floor : [];
const lineRelays = Array.isArray(state.relays?.line) ? state.relays.line : [];
const REPLACE_WITH_DEVICE_ID_01Relays = [...floorRelays, ...lineRelays];

function findRoom(keys) {
  const wanted = (Array.isArray(keys) ? keys : [keys]).map(norm);
  return rooms.find(r => wanted.includes(norm(r.key)) || wanted.includes(norm(r.name))) || null;
}
function findZoneRelay(relayHints) {
  const hints = (Array.isArray(relayHints) ? relayHints : [relayHints]).map(norm);
  return REPLACE_WITH_DEVICE_ID_01Relays.find(r => {
    const name = norm(r.name);
    return hints.some(h => name.includes(h)) && name.includes("futeskor");
  }) || null;
}
function findSystemRelay(hint) {
  const h = norm(hint);
  return REPLACE_WITH_DEVICE_ID_01Relays.find(r => norm(r.name).includes(h)) || null;
}

const zoneCfg = {
  nappali: { label: "Nappali", roomKeys: ["nappali"], relayHints: ["nappali"], base: BASE_SETPOINTS.nappali },
  halo:    { label: "Hálószoba", roomKeys: ["halo"], relayHints: ["haloszoba","halo"], base: BASE_SETPOINTS.halo },
  gyerek:  { label: "Gyerekszoba", roomKeys: ["gyerek","Gyerekszoba"], relayHints: ["Gyerekszoba","gyerek"], base: BASE_SETPOINTS.gyerek },
  furdo:   { label: "Fürdőszoba", roomKeys: ["furdo"], relayHints: ["furdo","furdoszoba"], base: BASE_SETPOINTS.furdo },
  wc:      { label: "WC", roomKeys: ["wc","wc t&h"], relayHints: ["wc"], base: BASE_SETPOINTS.wc }
};

// cache kulcsok (régi heating rules kompat)
const cacheKeys = { nappali:"ho_nappali", halo:"ho_halo", gyerek:"ho_gyerekszoba", furdo:"ho_furdo", wc:"ho_wc" };

function getTempWithCache(zoneKey, roomObj) {
  if (roomObj?.online === false) {
    flow.set(cacheKeys[zoneKey], null);
    flow.set(cacheKeys[zoneKey] + "_at", null);
    return { temp: null, source: "offline", ageMs: null };
  }
  const rawStamp = roomObj?.measuredAt;
  const measureAt = typeof rawStamp === "number" ? (rawStamp < 1e12 ? rawStamp*1000 : rawStamp) : Date.parse(rawStamp);
  const measurementOK = rawStamp == null || (Number.isFinite(measureAt) && nowMs-measureAt <= 75*60000 && measureAt <= nowMs+60000);
  const live = roomObj?.online === true && measurementOK ? num(roomObj?.temp) : null;
  if (roomObj && !measurementOK) return {temp:null,source:"stale",ageMs:nowMs-measureAt};
  if (okTemp(live)) {
    flow.set(cacheKeys[zoneKey], live);
    flow.set(`${cacheKeys[zoneKey]}_at`, nowMs);
    return { temp: live, source: "live", ageMs: 0 };
  }
  const cached = num(flow.get(cacheKeys[zoneKey]));
  const cachedAt = num(flow.get(`${cacheKeys[zoneKey]}_at`));
  const ageMs = cachedAt === null ? null : Math.max(0, nowMs - cachedAt);
  if (okTemp(cached) && ageMs !== null && ageMs <= SENSOR_CACHE_MAX_AGE_MS) {
    return { temp: cached, source: "cached", ageMs };
  }
  return { temp: null, source: null, ageMs };
}

function buildZone(zoneKey, cfg) {
  const room = findRoom(cfg.roomKeys);
  const relay = findZoneRelay(cfg.relayHints);
  const ov = zoneOverrides[zoneKey] || {};

  const manualTargetActive = isActiveUntil(ov.until);
  const manualForceOnActive = isActiveUntil(ov.forceOnUntil);
  const manualForceOffActive = isActiveUntil(ov.forceOffUntil);

  const nightAdj = (mode === "ejszaka") ? -NIGHT_DELTA : 0;
  const sleepBedroom = hybrid.sleep && (zoneKey === "halo" || zoneKey === "gyerek");
  const setpointRules = sleepBedroom ? 22 : hybrid.sleep && zoneKey === "nappali" ? 22 : cfg.base + wOff + nightAdj;

  let setpointEffective = setpointRules;
  if (manualTargetActive && num(ov.target) !== null) setpointEffective = num(ov.target);

  const { temp, source, ageMs } = getTempWithCache(zoneKey, room);
  const rh = num(room?.rh);

  const thresholdOn = (Number.isFinite(setpointEffective) ? (setpointEffective - HYST) : null);
  const thresholdOff = Number.isFinite(setpointEffective) ? setpointEffective : null;
  const relayOn = relay?.on === true;

  // Valódi hiszterézis: kikapcsolt kör csak az alsó küszöb alatt indul,
  // bekapcsolt kör a célértékig folytatja a fűtést.
  const wantsHeatByTemp = okTemp(temp) && Number.isFinite(setpointEffective) && (
    relayOn ? temp < thresholdOff : temp < thresholdOn
  );
  const wantsHeatRulesByTemp = okTemp(temp) && Number.isFinite(setpointRules) && (
    relayOn ? temp < setpointRules : temp < (setpointRules - HYST)
  );

  // “rules” vs “effective”
  const wantsHeatRules = wantsHeatRulesByTemp;

  const wantsHeatEffective =
    !manualForceOffActive && room?.online !== false && okTemp(temp) && (manualForceOnActive || wantsHeatByTemp);

  const heatDeficit =
    (okTemp(temp) && Number.isFinite(setpointEffective))
      ? Math.max(0, (setpointEffective - temp))
      : null;

  const error =
    (okTemp(temp) && Number.isFinite(setpointEffective))
      ? +(setpointEffective - temp).toFixed(2)
      : null;

  const furdoExceptionWindowActive =
    zoneKey === "furdo" && isBetweenHour(hour, SCHEDULE.furdo_kivetel.start, SCHEDULE.furdo_kivetel.end);

  return {
    key: zoneKey,
    label: cfg.label,

    sensor: {
      ok: room?.online !== false && (source === "live" || source === "cached"),
      name: room?.name || null,
      temp,
      tempSource: source,
      tempAgeMs: ageMs,
      fresh: source === "live" || (source === "cached" && ageMs <= SENSOR_CACHE_MAX_AGE_MS),
      rh
    },

    relay: {
      found: !!relay,
      device: relay?.device || null,
      channel: relay?.channel || null,
      name: relay?.name || null,
      state: relay?.state || "unknown",
      on: !!relay?.on
    },

    // ---- DOWNSTREAM KOMPAT: Zone planner + UI Publisher ezeket várja
    control: {
      targetRules: setpointRules,
      targetEffective: setpointEffective,
      hysteresis: HYST,
      thresholdOn,
      thresholdOff,
      error,
      heatDeficit,
      // “base” alatt itt az EFFECTIVE demandet adjuk, mert ez a tényleges vezérlés alapja.
      wantsHeatBase: !!wantsHeatEffective,
      wantsHeatRules: !!wantsHeatRules
    },

    rules: {
      compat: "heating_rules_v0.4.1",
      mode,
      baseSetpoint: cfg.base,
      nightDeltaApplied: nightAdj,
      weather: { tOutUsed, tOutSource, offset: wOff },
      setpointRules,
      setpointEffective,
      hysteresis: HYST,
      thresholdOn,
      thresholdOff,
      furdoExceptionWindowActive,
      wantsHeatRules,
      wantsHeatEffective,
      heatDeficit
    },

    override: {
      manualTargetActive,
      manualTargetUntil: ov.until || null,
      manualTarget: manualTargetActive ? num(ov.target) : null,

      manualForceOnActive,
      manualForceOnUntil: ov.forceOnUntil || null,
      manualForceOffActive,
      manualForceOffUntil: ov.forceOffUntil || null
    }
  };
}

// build zones
const zones = {};
for (const [k, cfg] of Object.entries(zoneCfg)) zones[k] = buildZone(k, cfg);
flow.set('hvac_zone_targets',Object.fromEntries(Object.entries(zones).map(([key,z])=>[key,z.control.targetEffective])));

// system relays
const boilerRelay = findSystemRelay("kazan");
const pumpRelay = findSystemRelay("szivattyu");

// AC availability (változatlan)
const lastCommunication = state.ac?.lastCommunication || null;
const lastTs = lastCommunication ? Date.parse(lastCommunication) : null;
const acAgeSec = Number.isFinite(lastTs) ? Math.round((nowMs - lastTs) / 1000) : null;
const acFresh = acAgeSec !== null && acAgeSec <= 15 * 60;
const acHasTelemetry =
  num(state.ac?.roomTemp) !== null ||
  num(state.ac?.setTemp) !== null ||
  num(state.ac?.modeCode) !== null;
const acPollAt = num(state.ac?.receivedAt);
const acPollFresh = acPollAt !== null && nowMs-acPollAt<=15*60000;
const acAvailable = state.ac?.offline !== true && !state.ac?.pending && (acFresh || (acPollFresh && acHasTelemetry));

// demand summary
const demandZonesRules = Object.values(zones).filter(z => z.rules.wantsHeatRules).map(z => z.key);
const demandZonesEffective = Object.values(zones).filter(z => z.rules.wantsHeatEffective).map(z => z.key);

msg.topic = "hvac/zone-context";
msg.payload = {
  meta: {
    builtAt: new Date().toISOString(),
    zoneContextVersion: 32,
    compat: "heating_rules_v0.4.1"
  },

  source: state,

  system: {
    hybrid,
    control: {floorMode:flow.get("hvac_floor_mode") || "auto"},
    time: state.time || null,

    outdoor: {
      tempNow: tOutNow,
      tempForecast: tOutForecast,
      tempUsedForComp: tOutUsed,
      tempSource: tOutSource,
      wx: state.outdoor?.wx ?? null,
      humidity: state.outdoor?.humidity ?? null,
      weatherOffset: wOff,
      forecast: state.outdoor?.forecast ?? null
    },

    heating: {
      mode,
      schedule: SCHEDULE,
      hysteresis: HYST,
      nightDelta: NIGHT_DELTA,
      baseSetpoints: BASE_SETPOINTS,

      demandZonesRules,
      demandZonesEffective,

      anyDemandRules: demandZonesRules.length > 0,
      anyDemandEffective: demandZonesEffective.length > 0,

      // ---- DOWNSTREAM KOMPAT: Climate planner/Zone planner régi neve
      anyBaseDemand: (demandZonesEffective.length > 0),
      demandZonesBase: demandZonesEffective
    },

    relays: {
      boiler: { found: !!boilerRelay, name: boilerRelay?.name || null, on: !!boilerRelay?.on },
      pump: { found: !!pumpRelay, name: pumpRelay?.name || null, on: !!pumpRelay?.on }
    },

    ac: {
      receivedAt: num(state.ac?.receivedAt),
      available: acAvailable,
      pending: !!state.ac?.pending,
      offline: !!state.ac?.offline,
      fresh: acFresh,
      ageSec: acAgeSec,
      roomTemp: num(state.ac?.roomTemp),
      setTemp: num(state.ac?.setTemp),
      modeCode: num(state.ac?.modeCode),
      power: typeof state.ac?.power === "boolean" ? state.ac.power : null
    }
  },

  zones
};

return msg;

// Zone planner v3.0 — forecast strategy, AC priority and safe post-run
// Input: hvac/zone-context (v3.1)
// Output: hvac/zone-plan

const ctx = msg.payload || {};
const zonesIn = ctx.zones || {};

function num(v) {
  if (v === null || v === undefined || v === "") return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}
function clone(obj) {
  return JSON.parse(JSON.stringify(obj));
}

const now = Date.now();

// anti short-cycle (ms) — heating_rules_v0.4.1 port
const MIN_ON = { kazan:180000, szivattyu:90000, nappali:120000, halo:120000, gyerek:120000, furdo:120000, wc:120000 };
const MIN_OFF= { kazan:60000,  szivattyu:30000, nappali:30000,  halo:30000,  gyerek:30000,  furdo:30000,  wc:30000 };

function applyAntiShortCycle(key, wantBool, currentOnBool) {
  const want  = wantBool ? 1 : 0;
  const curOn = currentOnBool ? 1 : 0;

  const kState = `hvac_floor_${key}`;
  const kAt    = `hvac_floor_${key}_at`;

  let last = flow.get(kState);
  let at = flow.get(kAt);
  // Track observations, never the planned state. A failed OFF request must
  // not be mistaken for a new physical ON transition on the next poll.
  if (typeof last !== "number" || typeof at !== "number") {
    last = curOn; at = 0;
  }
  if (last !== curOn) { last = curOn; at = now; }
  flow.set(kState, curOn);
  flow.set(kAt, at);
  const elapsed = now - at;
  let final = want;
  let hold = null;
  if (want === 1 && curOn === 0 && elapsed < (MIN_OFF[key] || 0)) { final = curOn; hold = "min_off_hold"; }
  if (want === 0 && curOn === 1 && elapsed < (MIN_ON[key] || 0)) { final = curOn; hold = "min_on_hold"; }

  return { final: !!final, hold, elapsedMs: elapsed };
}

// Shared calendar policy; automatic floor heat only in the morning.
const policy=ctx.system?.hybrid || {};
const cfg={morningStart:5,morningEnd:8,sleepStart:20,sleepEnd:5};
const outdoorTemp=num(ctx.system?.outdoor?.tempUsedForComp);
const forecastHigh=num(ctx.system?.outdoor?.forecast?.maxNextHours) ?? outdoorTemp;
const livingTemp=num(zonesIn.nappali?.sensor?.temp);
const floorMode=flow.get("hvac_floor_mode") || "auto";
const strategyMode=policy.floorAllowed?"morning_floor":policy.sleep?"night_temper":"daytime_ac";
const manualFloorDemand=Object.values(zonesIn).some(z=>z.override?.manualForceOnActive || z.override?.manualTargetActive);
const acHeating=ctx.system?.ac?.power===true && num(ctx.system?.ac?.modeCode)===1;
const floorHeatingAllowed=floorMode!=="off" && (policy.floorAllowed===true || manualFloorDemand || floorMode==="manual") && !acHeating;
const mildDay=false, acHeatPriority=policy.acHeatAllowed===true;

const zoneKeys = ["nappali", "halo", "gyerek", "furdo", "wc"];
const zonePlan = {};

for (const key of zoneKeys) {
  const z       = clone(zonesIn[key] || {});
  const reasons = [];

  const baseDemand = !!(z.control?.wantsHeatBase ?? z.rules?.wantsHeatEffective ?? false);
  const relayFound = z.relay?.found === true;
  const sensorFresh = z.sensor?.fresh !== false && num(z.sensor?.temp) !== null;
  const baseWant = baseDemand && relayFound && sensorFresh;

  const zoneManual = z.override?.manualForceOnActive || z.override?.manualTargetActive;
  const zoneAllowed = floorHeatingAllowed && (policy.floorAllowed===true || zoneManual || floorMode==="manual");
  let want = zoneAllowed && baseWant;
  if (baseWant)                      reasons.push("base_demand");
  if (baseDemand && !relayFound)     reasons.push("relay_unknown");
  if (baseDemand && !sensorFresh)    reasons.push("sensor_stale");
  if (!floorHeatingAllowed && baseWant) reasons.push("strategy_block");

  const relayOn = !!z.relay?.on;

  const asc = applyAntiShortCycle(key, want, relayOn);
  if (asc.hold) reasons.push(asc.hold);
  const wantFinal = asc.final;

  const action =
    wantFinal && !relayOn  ? "turn_on"  :
    !wantFinal && relayOn  ? "turn_off" :
    "keep";

  zonePlan[key] = {
    key:      z.key || key,
    label:    z.label || key,
    sensor:   z.sensor   || {},
    relay:    z.relay    || {},
    config:   z.config   || {},
    control:  z.control  || {},
    override: z.override || {},
    rules:    z.rules    || {},

    plan: {
      wantRaw: baseWant,
      want:    wantFinal,
      relayOn,
      action,
      reasons,
      antiShortCycle: { hold: asc.hold, elapsedMs: asc.elapsedMs }
    }
  };
}

// summary
const wantedZones      = Object.values(zonePlan).filter(z => z.plan.want).map(z => z.key);
const currentlyOnZones = Object.values(zonePlan).filter(z => z.plan.relayOn).map(z => z.key);
const anyZoneWant      = wantedZones.length > 0;

// plant
const boilerFound = ctx.system?.relays?.boiler?.found === true;
const pumpFound   = ctx.system?.relays?.pump?.found === true;
const boilerOn = boilerFound && ctx.system.relays.boiler.on === true;
const pumpOn   = pumpFound && ctx.system.relays.pump.on === true;

// Ismeretlen reléállapotból nem gyártunk parancsot. A minimumidők csak
// igazolt visszajelzésből indulnak, nem a korábban tervezett állapotból.
const boilerASC = boilerFound
  ? applyAntiShortCycle("kazan", anyZoneWant && floorHeatingAllowed, boilerOn)
  : { final: false, hold: "relay_unknown", elapsedMs: null };
const boilerWant = boilerASC.final;

const boilerAction = !boilerFound ? "keep" :
  boilerWant && !boilerOn  ? "turn_on"  :
  !boilerWant && boilerOn  ? "turn_off" :
  "keep";

// Az utókeringés már a kazán kikapcsolási parancsakor elindul. Az igazolt
// BE -> KI átmenet csak akkor indít új időzítést, ha nem ez a flow kérte a
// leállást. Így az 5 perces lekérdezés nem állítja le, majd indítja újra a pumpát.
const POST_RUN_MS = 3 * 60 * 1000;
const PREV_BOILER_KEY = "hvac_boiler_confirmed_on";
const POST_RUN_UNTIL_KEY = "hvac_pump_postrun_until";
const OFF_COMMAND_AT_KEY = "hvac_boiler_off_command_at";
const prevBoilerOn = flow.get(PREV_BOILER_KEY);
let postRunUntil = num(flow.get(POST_RUN_UNTIL_KEY)) ?? 0;
let offCommandAt = num(flow.get(OFF_COMMAND_AT_KEY));

if (boilerAction === "turn_off") {
  offCommandAt = now;
  postRunUntil = now + POST_RUN_MS;
  flow.set(OFF_COMMAND_AT_KEY, offCommandAt);
}

if (boilerFound) {
  if (prevBoilerOn === true && boilerOn === false) {
    const commandedRecently = offCommandAt !== null && (now - offCommandAt) < 15 * 60 * 1000;
    postRunUntil = commandedRecently ? offCommandAt + POST_RUN_MS : now + POST_RUN_MS;
    flow.set(OFF_COMMAND_AT_KEY, null);
    offCommandAt = null;
  }
  if (boilerOn === true && boilerAction !== "turn_off") postRunUntil = 0;
  flow.set(PREV_BOILER_KEY, boilerOn);
}
if (postRunUntil <= now) postRunUntil = 0;
flow.set(POST_RUN_UNTIL_KEY, postRunUntil);

const boilerRecentlyOff = boilerFound && postRunUntil > now &&
  (!boilerOn || boilerAction === "turn_off");
const pumpDemand = (anyZoneWant && floorHeatingAllowed) || boilerRecentlyOff;
const pumpASC = pumpFound
  ? applyAntiShortCycle("szivattyu", pumpDemand, pumpOn)
  : { final: false, hold: "relay_unknown", elapsedMs: null };
const pumpWant = pumpASC.final;

const pumpAction = !pumpFound ? "keep" :
  pumpWant && !pumpOn  ? "turn_on"  :
  !pumpWant && pumpOn  ? "turn_off" :
  "keep";

msg.topic   = "hvac/zone-plan";
msg.payload = {
  meta: { plannedAt: new Date().toISOString(), zonePlannerVersion: 30 },

  strategy: { mode: strategyMode, policy, floorHeatingAllowed, floorMode, outdoorTemp, forecastHigh,
              mildDay, acHeatPriority, livingTemp, thresholds: cfg },

  summary: {
    wantedZones,
    wantedCount:      wantedZones.length,
    currentlyOnZones,
    currentlyOnCount: currentlyOnZones.length,
    anyZoneWant
  },

  plant: {
    boiler: { found: boilerFound, currentOn: boilerOn, want: boilerWant, action: boilerAction, antiShortCycle: boilerASC },
    pump:   { found: pumpFound, currentOn: pumpOn, want: pumpWant, action: pumpAction, antiShortCycle: pumpASC,
              postRunActive: boilerRecentlyOff, postRunUntil: postRunUntil ? new Date(postRunUntil).toISOString() : null }
  },

  zones: zonePlan
};

return msg;

const plan = msg.payload || {};
const zones = plan.zones || {};

// --- iHost device mapping (nálad fix)
const DEV = {
  F: { name: "Fűtés F", deviceId: "REPLACE_WITH_DEVICE_ID_02" },
  L: { name: "Fűtés L", deviceId: "REPLACE_WITH_DEVICE_ID_03" },
};

// --- csatornák száma a relé modulokon
const CHANNELS = ["1", "2", "3", "4"];

// --- helper: üres multi map
function blankMulti() {
  const m = {};
  for (const ch of CHANNELS) m[ch] = "keep";
  return m;
}

// --- helper: "turn_on"/"turn_off"/"keep" -> "on"/"off"/"keep"
function toMultiAction(action) {
  if (action === "turn_on") return "on";
  if (action === "turn_off") return "off";
  return "keep";
}

// --- készítsünk két multi parancsot (F és L)
const multiF = blankMulti();
const multiL = blankMulti();

// --- zónákból relé-parancsok
const perZone = {};
let changes = 0;

for (const [key, z] of Object.entries(zones)) {
  const a = z?.plan?.action || "keep";
  const want = !!z?.plan?.want;

  perZone[key] = {
    want,
    relayOn: !!z?.plan?.relayOn,
    action: a,
    reasons: z?.plan?.reasons || [],
    relay: z?.relay || {}
  };

  if (a === "keep") continue;

  const devName = z?.relay?.device;
  const ch = String(z?.relay?.channel || "");

  if (!ch || !CHANNELS.includes(ch)) continue;

  const mAct = toMultiAction(a);

  if (devName === DEV.F.name) {
    multiF[ch] = mAct;
    changes++;
  } else if (devName === DEV.L.name) {
    multiL[ch] = mAct;
    changes++;
  }
}

// --- kazán/szivattyú (a te rendszeredben: F ch4 = Kazán, L ch4 = Szivattyú)
if (plan?.plant?.boiler?.action && plan.plant.boiler.action !== "keep") {
  multiF["4"] = toMultiAction(plan.plant.boiler.action);
  changes++;
}
if (plan?.plant?.pump?.action && plan.plant.pump.action !== "keep") {
  multiL["4"] = toMultiAction(plan.plant.pump.action);
  changes++;
}

// --- építsük meg a “control-device list” JSON-t (amit a node-ok használnak)
const cmdF = {
  type: "multi",
  deviceId: DEV.F.deviceId,
  multi: multiF
};
const cmdL = {
  type: "multi",
  deviceId: DEV.L.deviceId,
  multi: multiL
};

// --- emberi összegzés
const wantedZones = plan?.summary?.wantedZones || [];
const onZones = plan?.summary?.currentlyOnZones || [];

node.status({
  fill: changes ? "yellow" : "green",
  shape: changes ? "dot" : "ring",
  text: `prod | want:${wantedZones.join(",") || "-"} | on:${onZones.join(",") || "-"} | changes:${changes}`
});

msg.topic = "hvac/floor-exec/dryrun";
msg.payload = {
  meta: {
    builtAt: new Date().toISOString(),
    executorVersion: 1,
    changes
  },
  strategy: plan.strategy || {},
  summary: plan.summary || {},
  plant: plan.plant || {},
  perZone,
  ihost: {
    F: { device: DEV.F, list: cmdF },
    L: { device: DEV.L, list: cmdL }
  }
};

return msg;

// A/C demand follows the external living sensor, never the unit intake sensor.
const ctx=msg.payload || {}, sys=ctx.system || {}, zones=ctx.zones || {};
const policy=sys.hybrid;
const num=v=>v!==null && v!==undefined && v!=='' && Number.isFinite(Number(v))?Number(v):null;
const living=zones.nappali?.sensor || {};
const refTemp=num(living.temp);
const sensorOK=living.ok===true && living.fresh===true && refTemp!==null;
const ac=sys.ac || {}, modeCode=num(ac.modeCode);
const owned=flow.get('hvac_ac_automation_owned')===true;
const autoMode=flow.get('hvac_ac_auto_mode');
const heatRunning=(ac.power===true && modeCode===1) || (owned && autoMode==='heat');
const coolingRunning=(ac.power===true && modeCode===2) || (owned && autoMode==='cooling');
const floorActive=sys.relays?.boiler?.on===true || Object.values(zones).some(z=>z.relay?.on===true);
const explicitFloor=Object.values(zones).some(z=>z.override?.manualForceOnActive || z.override?.manualTargetActive);
const outdoor=num(sys.outdoor?.tempNow);
const forecastHigh=num(sys.outdoor?.forecast?.maxNextHours) ?? outdoor;
const warmDay=sys.time?.seasonHint==='summer' && outdoor!==null && outdoor>=24 && forecastHigh>=24;
let mode='idle', reason='no_heat_demand', command=null;
const heatStop=policy?.heatOff ?? 25;
const forceHeatStop=heatRunning && (!sensorOK || refTemp>=heatStop || policy?.acHeatAllowed===false || explicitFloor);
if(forceHeatStop){reason=!sensorOK?'living_sensor_invalid':refTemp>=heatStop?'living_sensor_target_reached':'morning_floor_priority';command={power:'off'};}
else if(policy && sensorOK && ac.available===true && !ac.pending) {
 if(warmDay && (refTemp>=24.4 || (coolingRunning && refTemp>24))) {
  mode='cooling';reason='summer_external_sensor';command={power:'on',mode:'cooling',temperature:24,fanspeed:3};
 } else if(policy.acHeatAllowed && !warmDay && !floorActive && !explicitFloor && !zones.nappali?.override?.manualForceOffActive &&
   (refTemp<policy.heatOn || (heatRunning && refTemp<policy.heatOff))) {
  mode='air_temper';reason=policy.sleep?'night_temper_22':'daytime_ac_support';
  command={power:'on',mode:'heat',temperature:policy.sleep?24:27,fanspeed:3};
 } else if(policy.floorAllowed) reason='morning_floor_priority';
 else if(floorActive || explicitFloor) reason='floor_handover_wait';
} else if(!sensorOK) reason='living_sensor_invalid';
else if(ac.available!==true) reason='ac_unavailable';
msg.topic='hvac/climate-plan';
msg.payload={meta:{plannedAt:new Date().toISOString(),climatePlannerVersion:40},mode,reason,command,
 inputs:{refTemp,livingSensorOK:sensorOK,heatStop,forceHeatStop,
  acPower:ac.power,acModeCode:modeCode,acAvailable:ac.available,acPending:!!ac.pending,
  acReadbackAt:ac.receivedAt,acOffline:ac.offline,
  automationOwned:owned,autoMode,heatingDemand:sys.heating?.anyDemandEffective===true,
  floorActive,explicitFloor,calendarSeason:sys.time?.seasonHint,policy,outdoorTemp:outdoor,forecastHigh},
 thresholds:{heatIndoorOn:policy?.heatOn,heatIndoorOff:heatStop,coolingIndoorOn:24.4,coolingIndoorOff:24}};
flow.set('hvac_climate_plan',msg.payload);
node.status({fill:command?.power==='off'?'grey':command?'yellow':'green',shape:'dot',text:`${reason} · ${refTemp ?? '—'}°C`});
return msg;

const plan = msg.payload || {};

const BUILDING_ID = "1106921";
const DEVICE_ID = "REPLACE_WITH_DEVICE_ID_18";

const effective = plan.effective || plan;
const cmd = effective.command || null;

msg.topic = "hvac/ac-exec/dryrun";
msg.payload = {
  meta: { builtAt: new Date().toISOString(), executorVersion: 1 },
  plan,
  effective,
  melcloud: cmd ? {
    device: {
      buildingid: BUILDING_ID,
      deviceid: DEVICE_ID,
      command: cmd
    }
  } : null
};

node.status({
  fill: cmd ? "yellow" : "green",
  shape: cmd ? "dot" : "ring",
  text: cmd ? `prod | AC ${cmd.mode} ${cmd.temperature ?? ""}` : "prod | AC idle"
});

return msg;

// input: hvac/zone-context
const ctx = msg.payload || {};
const now = Date.now();

// későbbre: globális padló módok
const floorMode = flow.get("hvac_floor_mode") || "auto"; // auto | off | manual
// most még csak átadjuk, de kitehetjük a payloadba

ctx.system = ctx.system || {};
ctx.system.control = ctx.system.control || {};
ctx.system.control.floorMode = floorMode;

msg.topic = "hvac/zone-context";
msg.payload = ctx;
return msg;

const plan=msg.payload || {}, now=Date.now();
const override=flow.get('hvac_ac_override');
let effective={mode:plan.mode || 'idle',reason:plan.reason || 'planner',command:plan.command || null,
 source:'planner',overrideActive:false,overrideUntil:null};
if(override?.enabled){
 if(Date.parse(override.until)>now && override.command)
  effective={mode:'override',reason:'manual_override',command:override.command,source:'override',overrideActive:true,overrideUntil:override.until};
 else flow.set('hvac_ac_override',null);
}
const owned=flow.get('hvac_ac_automation_owned')===true;
if(!effective.overrideActive && !effective.command && owned && plan.inputs?.acPower!==false){
 effective={...effective,mode:'idle',reason:'automatic_demand_cleared',command:{power:'off'},source:'planner_stop'};
}
// Unknown/missing telemetry is never interpreted as a confirmed OFF state.
if(plan.inputs?.acPower===false && plan.inputs?.acOffline!==true && !plan.inputs?.acPending &&
   Number(plan.inputs?.acReadbackAt)>Number(flow.get('hvac_ac_last_command_at') || 0) && !effective.command){
 flow.set('hvac_ac_automation_owned',false);flow.set('hvac_ac_auto_mode',null);
}
// User requested external-sensor control, including inherited/manual heating.
if(plan.inputs?.forceHeatStop===true){
 effective={mode:'idle',reason:plan.reason,command:{power:'off'},source:'external_sensor_limit',overrideActive:false,overrideUntil:null};
}
msg.topic='hvac/climate-effective';
msg.payload={meta:{decidedAt:new Date().toISOString(),arbitrationVersion:2},planner:plan,effective};
return msg;

// Floor APPLY v3.0 — route dynamic plan to fixed control-device nodes
const enabled = flow.get("hvac_control_enabled") === true;
const OUTPUTS = 14;
const out = Array(OUTPUTS).fill(null);

if (!enabled) {
  node.status({ fill: "grey", shape: "ring", text: "APPLY | DISABLED" });
  return out;
}

const p = msg.payload || {};
const multiF = p?.ihost?.F?.list?.multi || {};
const multiL = p?.ihost?.L?.list?.multi || {};

function normAct(act) {
  const a = String(act ?? "").toLowerCase().trim();
  if (a === "on" || a === "off") return a;
  if (a === "true" || a === "1") return "on";
  if (a === "false" || a === "0") return "off";
  return null;
}

function commandsFor(multi, routes, lastKey, lastAtKey) {
  const commands = [];
  const sigObj = {};
  for (const [channel, indexes] of Object.entries(routes)) {
    const action = normAct(multi[channel]);
    if (!action) continue;
    sigObj[channel] = action;
    commands.push({ channel, action, index: action === "on" ? indexes[0] : indexes[1] });
  }
  if (!commands.length) return { commands: [], dedup: false };

  const sig = JSON.stringify(sigObj);
  const last = flow.get(lastKey);
  const lastAt = Number(flow.get(lastAtKey)) || 0;
  if (last === sig && Date.now() - lastAt < 60 * 1000) {
    return { commands: [], dedup: true };
  }
  flow.set(lastKey, sig);
  flow.set(lastAtKey, Date.now());
  return { commands, dedup: false };
}

const f = commandsFor(multiF, { "4": [0, 1], "2": [4, 5], "1": [10, 11] }, "last_apply_sig_F", "last_apply_at_F");
const l = commandsFor(multiL, { "4": [2, 3], "2": [6, 7], "1": [8, 9], "3": [12, 13] }, "last_apply_sig_L", "last_apply_at_L");
const commands = [...f.commands, ...l.commands];

for (const command of commands) {
  out[command.index] = {
    topic: "hvac/floor-exec/apply",
    payload: { channel: command.channel, action: command.action },
  };
}

node.status({
  fill: commands.length ? "green" : "grey",
  shape: commands.length ? "dot" : "ring",
  text: commands.length ? `APPLY | relays:${commands.length}` : (f.dedup || l.dedup ? "APPLY | dedup" : "APPLY | noop"),
});

return out;

// A/C APPLY v1.4 — dedicated MELCloud branches: output 1 heat, output 2 cooling
const enabled = flow.get("hvac_control_enabled") === true;
if (!enabled) {
  node.status({ fill: "grey", shape: "ring", text: "APPLY | DISABLED" });
  return null;
}

const p = msg.payload || {};
const dev = p?.melcloud?.device || null;
const cmd = dev?.command || null;

if (!dev || !cmd) {
  node.status({ fill: "grey", shape: "ring", text: "APPLY | AC noop" });
  return null;
}

const command = { ...cmd };
if (command.temperature !== undefined && command.settemperature === undefined) {
  command.settemperature = command.temperature;
}
if (command.fanspeed !== undefined && command.setfanspeed === undefined) {
  command.setfanspeed = command.fanspeed;
}

function normalizeMode(value) {
  const mode = String(value || "").toLowerCase();
  if (mode === "heat" || mode === "heating") return "heat";
  if (mode === "cool" || mode === "cooling") return "cooling";
  if (mode === "dry" || mode === "drying") return "dry";
  return null;
}

const previousMode = normalizeMode(flow.get("hvac_ac_auto_mode"));
const reportedModeCode = Number(p?.plan?.planner?.inputs?.acModeCode);
let routeMode = normalizeMode(command.mode);

// A kikapcsolási parancs ugyanarra az ágra menjen, amelyik az automatikus
// működést elindította. Újraindítás utáni tartalék a MELCloud mód-visszajelzés.
if (command.power === "off") {
  routeMode = previousMode;
  if (!routeMode && reportedModeCode === 1) routeMode = "heat";
  if (!routeMode && reportedModeCode === 2) routeMode = "cooling";
}

// Nincs külön szárító MELCloud node. A dry parancsot nem küldjük a hűtési
// ágra, mert a fix cooling beállítás abból tényleges hűtést csinálna.
if (routeMode === "dry") {
  node.status({ fill: "yellow", shape: "ring", text: "APPLY | dry tiltva" });
  return null;
}

if (routeMode !== "heat" && routeMode !== "cooling") {
  node.status({ fill: "red", shape: "ring", text: "APPLY | ismeretlen AC mód" });
  node.warn("A/C APPLY: a parancs nem irányítható biztonságosan fűtés vagy hűtés ágra");
  return null;
}

const commandSig = routeMode + ":" + JSON.stringify(command);
const lastSig = flow.get("hvac_ac_last_command_sig");
const lastAt = Number(flow.get("hvac_ac_last_command_at")) || 0;
if (lastSig === commandSig && Date.now() - lastAt < 60 * 1000) {
  node.status({ fill: "grey", shape: "ring", text: `APPLY | ${routeMode} dedup <60s` });
  return null;
}

flow.set("hvac_ac_last_command_sig", commandSig);
flow.set("hvac_ac_last_command_at", Date.now());

msg.topic = routeMode === "heat" ? "hvac/ac-exec/heat" : "hvac/ac-exec/cooling";
msg.device = {
  buildingid: dev.buildingid,
  deviceid: dev.deviceid,
  command
};
msg.payload = msg.device;

if (command.power === "on") {
  flow.set("hvac_ac_automation_owned", true);
  flow.set("hvac_ac_auto_mode", routeMode);
}
if (command.power === "off") {
  // Keep ownership until a real OFF readback; retries must survive a failed command.
  flow.set("hvac_ac_stop_requested_at", Date.now());
}

node.status({
  fill: routeMode === "heat" ? "red" : "blue",
  shape: "dot",
  text: `APPLY | ${routeMode} ${command.temperature ?? command.settemperature ?? ""}`
});

// 1. kimenet: fűtés, 2. kimenet: hűtés
return routeMode === "heat" ? [msg, null] : [null, msg];

// Home Registry (init) — v3 (endpoint meta for multi-relays)
// Injecteld egyszer deploy után (vagy once-at-start), majd futtasd a UI Seeder-t is.

const REG_KEY = "home_registry";

const registry = {
  // --- Shutters
  "REPLACE_WITH_DEVICE_ID_15": { name: "Nappali redőny I", room: "Nappali", kind: "shutter" },
  "REPLACE_WITH_DEVICE_ID_16": { name: "Nappali redőny II", room: "Nappali", kind: "shutter" },
  "REPLACE_WITH_DEVICE_ID_14": { name: "Hálószoba redőny I", room: "Hálószoba", kind: "shutter" },
  "REPLACE_WITH_DEVICE_ID_13": { name: "Hálószoba redőny II", room: "Hálószoba", kind: "shutter" },
  "REPLACE_WITH_DEVICE_ID_11": { name: "Gyerekszoba redőny I", room: "Gyerekszoba", kind: "shutter" },
  "REPLACE_WITH_DEVICE_ID_12": { name: "Gyerekszoba redőny II", room: "Gyerekszoba", kind: "shutter" },

