    "WC T&H":          "wc"
};

const devices = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
const out = [];

devices.forEach(dev => {
    const room = ROOM_MAP[dev.name];
    if (!room) return;
    out.push({
