        online:  dev.online
    });
});

msg.payload = out;

// ── Node status ──────────────────────────────────────────────
const sensors = msg.payload;

const offline  = sensors.filter(s => !s.online);
const lowBat   = sensors.filter(s => s.battery !== null && s.battery < 20);
const total    = sensors.length;
const online   = sensors.filter(s => s.online).length;

if (total === 0) {
    node.status({ fill: "red", shape: "ring", text: "⚠️ Nincs szenzor" });
    return msg;
}

if (offline.length > 0) {
    const names = offline.map(s => s.room).join(", ");
    node.status({ fill: "red", shape: "ring", text: `⚠️ Offline: ${names}` });
    return msg;
}

if (lowBat.length > 0) {
    const names = lowBat.map(s => `${s.room}(${s.battery}%)`).join(", ");
    node.status({ fill: "yellow", shape: "dot", text: `🪫 ${names}` });
    return msg;
}

// Minden OK → átlagok mutatása
const temps = sensors.filter(s => s.temp !== null).map(s => s.temp);
const hums  = sensors.filter(s => s.hum  !== null).map(s => s.hum);
const avgT  = (temps.reduce((a, b) => a + b, 0) / temps.length).toFixed(1);
const avgH  = Math.round(hums.reduce((a, b) => a + b, 0) / hums.length);

node.status({
    fill:  "green",
    shape: "dot",
    text:  `✅ ${online}/${total}  🌡️ ${avgT}°C  💧${avgH}%`
});

return msg;

