if(!pending){node.status({fill:'red',shape:'ring',text:'A párosítási kód hibás vagy lejárt'});return null;}
data.grants=data.grants.filter(g=>g.until>now&&g.hash!==pending.hash);data.grants.push({hash:pending.hash,until:now+90*24*60*60000,approvedAt:now});
data.pending=data.pending.filter(p=>p.hash!==pending.hash);saveAccess(data);node.status({fill:'green',shape:'dot',text:'Kijelző engedélyezve · '+code});return null;

const authFile='/data/dutch-turf-camera/access.json';
const uiPaths=["/nscompact/","/nsdesktop2/","/dutch-turf/","/nspanel/"];
function loadAccess(){try{return JSON.parse(fs.readFileSync(authFile,'utf8'));}catch(e){return {grants:[],pending:[]};}}
function saveAccess(data){fs.mkdirSync('/data/dutch-turf-camera',{recursive:true,mode:0o700});fs.writeFileSync(authFile+'.tmp',JSON.stringify(data),{mode:0o600});fs.renameSync(authFile+'.tmp',authFile);fs.chmodSync(authFile,0o600);}
function tokenHash(token){return crypto.createHash('sha256').update(token).digest('hex');}
function tokenFrom(req){const part=String(req.headers.cookie||'').split(';').map(v=>v.trim()).find(v=>v.startsWith('dt_camera='));const value=part?part.slice(10):'';return /^[a-f0-9]{64}$/.test(value)?value:null;}
function fromUi(req){const origin='http://'+req.headers.host,ref=String(req.headers.referer||'');if(!ref.startsWith(origin+'/')||(req.headers.origin&&req.headers.origin!==origin))return false;const path=ref.slice(origin.length).split(/[?#]/)[0];return uiPaths.some(p=>path===p.slice(0,-1)||path.startsWith(p));}
function hasCameraAccess(req){if(!fromUi(req))return false;const token=tokenFrom(req);return !!token&&loadAccess().grants.some(g=>g.hash===tokenHash(token)&&g.until>Date.now());}

// Authenticated, on-demand H.264 remux. No transcoding or persistent camera worker.
msg.headers={'Cache-Control':'no-store, max-age=0','X-Content-Type-Options':'nosniff'};
function fail(status,error){msg.statusCode=status;msg.headers['Content-Type']='application/json';msg.payload={error};return msg;}
if(!hasCameraAccess(msg.req))return fail(401,'Ehhez a böngészőhöz még nincs kamerahozzáférés.');
let registry;
try{registry=JSON.parse(fs.readFileSync('/data/dutch-turf-camera/cameras.json','utf8'));}catch(e){return fail(503,'A kameralista még nem érhető el.');}
const camera=registry.cameras.find(c=>c.id===String(msg.req.params.id));
if(!camera)return fail(404,'Ismeretlen kamera.');
if(!camera.online||Date.now()-registry.updatedAt>900000)return fail(503,'A kamera nem elérhető.');
const jobs=globalThis.__dutchCameraJobs||(globalThis.__dutchCameraJobs=new Set());
if(jobs.size){msg.headers['Retry-After']='3';return fail(429,'Egy másik kameranézet már nyitva van. Zárd be, majd próbáld újra.');}
const res=msg.res?._res;if(!res)return null;
let child,closed=false,timer,bytes=0,startedAt=Date.now();
function close(status){
 if(closed)return;closed=true;clearTimeout(timer);
 if(child)child.kill('SIGKILL');
 if(!res.destroyed){if(!res.headersSent){res.writeHead(status===200?502:status,{'Content-Type':'application/json','Cache-Control':'no-store'});res.end(JSON.stringify({error:'Az élőkép megszakadt. Újracsatlakozás szükséges.'}));}else res.end();}
 context.set('live_state',{active:0,lastStatus:status,startedAt,endedAt:Date.now(),bytes});
 node.status({fill:'grey',shape:'ring',text:'Élőkép leállítva'});node.done();
}
function watchdog(){clearTimeout(timer);timer=setTimeout(()=>close(504),15000);}
try{
 child=childProcess.spawn('/data/dutch-turf-camera/ffmpeg',['-hide_banner','-loglevel','error','-nostdin','-rtsp_transport','tcp','-timeout','6000000','-analyzeduration','1000000','-probesize','1000000','-i',camera.url,'-map','0:v:0','-an','-c:v','copy','-f','mp4','-movflags','empty_moov+default_base_moof+frag_keyframe','-frag_duration','250000','-flush_packets','1','pipe:1'],{stdio:['ignore','pipe','pipe']});
 jobs.add(child);res.setTimeout(0);watchdog();
 context.set('live_state',{active:1,startedAt,bytes:0});node.status({fill:'blue',shape:'dot',text:'Élőkép · kapcsolódás'});
 res.once('close',()=>close(200));res.on('drain',()=>{if(!closed)child.stdout.resume();});
 child.stdout.on('data',chunk=>{
  if(closed)return;watchdog();bytes+=chunk.length;
  if(!res.headersSent)res.writeHead(200,{'Content-Type':'video/mp4','Cache-Control':'no-store, no-transform','X-Content-Type-Options':'nosniff','X-Accel-Buffering':'no'});
  if(!res.write(chunk))child.stdout.pause();
  node.status({fill:'green',shape:'dot',text:'Élőkép · H.264 továbbítás'});
 });
 child.stderr.on('data',()=>{}); // Credentials must never enter logs or responses.
 child.once('error',()=>close(503));
 child.once('close',()=>{jobs.delete(child);close(502);});
}catch(e){close(503);}
return;
